% bench_matlab_vs_python.m — MATLAB MGGP benchmark for comparison with Python.
%
% Reads data/siso_ref.csv (generated by generate_dataset.m), runs evoluir for
% each seed with the agreed comparison params (see PROTOCOL.md), and saves
% results to results/matlab_bench_<timestamp>.json.
%
% Executar de dev/comparison/:  run bench_matlab_vs_python

clear; clc;

scriptDir = fileparts(mfilename('fullpath'));
RESULTS_DIR = fullfile(scriptDir, 'results');
MATLAB_SRC  = fullfile(scriptDir, '..', '..', 'src');

if ~exist(RESULTS_DIR, 'dir'), mkdir(RESULTS_DIR); end
if ~exist('evoluir', 'file'), addpath(MATLAB_SRC); end

%% ─── PARAMS (alinhados com PROTOCOL.md) ──────────────────────────────────────
SEEDS     = [42, 43, 44];
POP_SIZE  = 100;
N_GER     = 50;
MAX_DELAY = 3;          % max(nDelays=[1,2,3])
N_TERMS   = 5;
MAX_FAT   = 2;
K_WINDOW  = 5;
SPLIT     = 0.7;

THRESHOLD_CONV = 0.05;  % fitness < este valor = convergiu

%% ─── LOAD DATASET ────────────────────────────────────────────────────────────
csvPath = fullfile(scriptDir, 'data', 'siso_ref.csv');
if ~exist(csvPath, 'file')
    error('bench_matlab_vs_python:noDataset', ...
        'Dataset nao encontrado: %s\nExecute generate_dataset.m primeiro.', csvPath);
end

T    = readtable(csvPath);
y    = T.y;
u1   = T.u1;
N    = numel(y);
n_id = round(N * SPLIT);

y_id  = y(1:n_id);   u_id  = u1(1:n_id);
y_val = y(n_id+1:end); u_val = u1(n_id+1:end);
fprintf('Dataset: %d total  %d id  %d val\n', N, n_id, N - n_id);

%% ─── CONFIG BASE ─────────────────────────────────────────────────────────────
baseCfg.nomesEntradas       = {'u1'};
baseCfg.maxFatoresPorTermo  = MAX_FAT;
baseCfg.popSize             = POP_SIZE;
baseCfg.nGeracoes           = N_GER;
baseCfg.maxDelay            = MAX_DELAY;
baseCfg.numTermosInicial    = N_TERMS;
baseCfg.tipoFitness         = 'mShooting';
baseCfg.janelaMShooting     = K_WINDOW;
baseCfg.cxpb                = 0.8;
baseCfg.mtpb                = 0.1;
baseCfg.tamanhoTorneio      = 2;
baseCfg.elite               = 0.10;
baseCfg.verbose             = false;

% sequential run (no parfor) for fair single-thread comparison
seqCfg           = baseCfg;
seqCfg.usarParfor = false;

% parfor run for MATLAB-best comparison
parCfg           = baseCfg;
parCfg.usarParfor = true;

%% ─── RUN SEEDS ───────────────────────────────────────────────────────────────
seqResults = cell(numel(SEEDS), 1);
parResults = cell(numel(SEEDS), 1);

for si = 1:numel(SEEDS)
    seed = SEEDS(si);
    rng(seed);
    fprintf('\n=== seed %d ===\n', seed);

    for mode = {'seq', 'par'}
        modeStr = mode{1};
        cfg = seqCfg;
        if strcmp(modeStr, 'par'), cfg = parCfg; end

        cfg.vars   = struct('y', y_id, 'u1', u_id);
        cfg.verbose = false;

        rng(seed);
        t0 = tic;
        [model, theta, hist] = evoluir(cfg);
        wall = toc(t0);

        % OSA-RMSE on validation
        varsVal.y  = y_val;
        varsVal.u1 = u_val;
        terms     = model.compile();
        maxLag    = model.maiorAtraso();
        try
            P_val = makeRegressors(terms, varsVal, maxLag);
            y_osa = P_val * theta;
            osa   = sqrt(mean((y_val(maxLag+1:end) - y_osa).^2));
        catch
            osa = Inf;
        end

        % FR-RMSE on validation
        try
            y0      = y_val(1:maxLag);
            inputs_val = struct('u1', u_val(maxLag+1:end));
            yFull   = predictFreeRun(theta, terms, y0, inputs_val);
            yPred   = yFull(maxLag+1:end);
            yTrue   = y_val(maxLag+1:end);
            n_fr    = min(numel(yPred), numel(yTrue));
            fr      = sqrt(mean((yTrue(1:n_fr) - yPred(1:n_fr)).^2));
        catch
            fr = Inf;
        end

        % convergence generation (first gen with best fitness < threshold)
        conv_g = -1;
        for g = 1:numel(hist)
            if isfinite(hist(g).melhorFitness) && hist(g).melhorFitness < THRESHOLD_CONV
                conv_g = hist(g).geracao;
                break;
            end
        end

        tpg_ms    = wall / N_GER * 1000;
        throughput = (POP_SIZE * N_GER) / wall;

        % peak RAM (Windows: feature('memstats'); fallback to NaN)
        try
            mem_s   = feature('memstats');
            peak_mb = (mem_s.SystemMemory.Available) / 1e6;  % available, not peak; best we have
        catch
            peak_mb = NaN;
        end

        r = struct( ...
            'seed',            seed,         ...
            'mode',            modeStr,      ...
            'wall_s',          round(wall, 3), ...
            'tpg_ms',          round(tpg_ms, 1), ...
            'throughput_eps',  round(throughput, 1), ...
            'peak_ram_mb',     round(peak_mb, 1), ...
            'osa_rmse_val',    round(osa, 6), ...
            'fr_rmse_val',     round(fr, 6),  ...
            'convergence_gen', conv_g         ...
        );

        fprintf('  [%s] wall=%.1fs  t/gen=%.0fms  OSA=%.6f  FR=%.6f  conv=%d\n', ...
            modeStr, wall, tpg_ms, osa, fr, conv_g);

        if strcmp(modeStr, 'seq')
            seqResults{si} = r;
        else
            parResults{si} = r;
        end
    end
end

%% ─── SUMMARY ─────────────────────────────────────────────────────────────────
fprintf('\n%s\n', repmat('=', 1, 60));
fprintf('Summary (mean ± std across %d seeds)\n', numel(SEEDS));
for modeStr = {'seq', 'par'}
    res = seqResults;
    if strcmp(modeStr, 'par'), res = parResults; end
    fields = {'wall_s','tpg_ms','throughput_eps','osa_rmse_val','fr_rmse_val'};
    vals   = zeros(numel(SEEDS), numel(fields));
    for si = 1:numel(SEEDS)
        for fi = 1:numel(fields)
            vals(si, fi) = res{si}.(fields{fi});
        end
    end
    m = mean(vals, 1, 'omitnan');
    s = std(vals, 0, 1, 'omitnan');
    fprintf('\n[%s]\n', modeStr{1});
    for fi = 1:numel(fields)
        fprintf('  %-20s %.4f ± %.4f\n', fields{fi}, m(fi), s(fi));
    end
end

%% ─── SAVE JSON ───────────────────────────────────────────────────────────────
cfg_out = struct( ...
    'popSize',    POP_SIZE,    ...
    'nGeracoes',  N_GER,       ...
    'maxDelay',   MAX_DELAY,   ...
    'nTerms',     N_TERMS,     ...
    'maxFatores', MAX_FAT,     ...
    'evalType',   'mShooting', ...
    'k',          K_WINDOW,    ...
    'seeds',      SEEDS        ...
);

output = struct( ...
    'timestamp',     char(datetime('now', 'Format', "yyyy-MM-dd'T'HH:mm:ss")), ...
    'library',       'matlab',                 ...
    'matlabVersion', version,                  ...
    'config',        cfg_out,                  ...
    'seq',           {seqResults},             ...
    'par',           {parResults}              ...
);

ts      = char(datetime('now', 'Format', 'yyyyMMdd_HHmmss'));
outPath = fullfile(RESULTS_DIR, sprintf('matlab_bench_%s.json', ts));
fid     = fopen(outPath, 'w');
fwrite(fid, jsonencode(output, 'PrettyPrint', true));
fclose(fid);
fprintf('\nResultados: %s\n', outPath);
